function renderLadderVisual(field){
 const box=document.getElementById('ladderSnapshot');if(!box)return;const top=field.slice(0,3),wasOpen=!!box.querySelector('details')?.open;
 const podium=top.map((h,i)=>`<button class="podium-runner podium-${i+1}" data-podium-horse="${esc(h.name)}" aria-label="Original form rank ${i+1}: ${esc(h.display)}"><span class="podium-rank">${i+1}</span>${silk(h,'large')}<b>${esc(h.display)}</b><small>No. ${h.number}</small></button>`).join('');
 const links=top.slice(0,-1).map((a,i)=>{const b=top[i+1],c=M.comparison(graph,a.name,b.name),steps=M.path(graph,a.name,b.name,3),caption=c.kind==='direct'?'Direct meeting':steps?'Shared-race path':'Different form groups';return `<article class="visual-path"><h4>${esc(a.display)} <span>↔</span> ${esc(b.display)}</h4><p class="path-kind">${caption}</p>${steps?`<div class="mini-chain"><div class="chain-node">${esc(display(steps[0].from))}</div>${steps.map(s=>`<div class="chain-edge"><b>${fmt(Math.abs(s.delta))}L ${s.delta>=0?'ahead of':'behind'} ↓</b><small>${esc(s.edge.race.track)} · ${shortDate(s.edge.race.date)} · ${s.edge.race.distance}m</small></div><div class="chain-node">${esc(display(s.to))}</div>`).join('')}</div>`:'<p class="mail-quiet">No short shared-race link supports this ordering. Their relative ranking is uncertain.</p>'}</article>`}).join('');
 box.innerHTML=`<div class="snapshot-heading"><span>THE FORM PODIUM</span><small>Original history</small></div><div class="podium-leaders">${podium||'<p>No supported runners to display.</p>'}</div><p class="podium-note">A form order, not a predicted finish or win chance.</p><details class="podium-evidence" ${wasOpen?'open':''}><summary>Expand the shared-race links <span>↗</span></summary>${links||'<p class="mail-quiet">More comparable race history is needed to draw a connection.</p>'}<p class="mail-quiet">Each arrow is a historical margin. Conditions, weights and pace can reverse the result; a chain is not a forecast margin.</p><a href="${esc(race.source)}" target="_blank" rel="noopener">Published race history ↗</a></details>`;
 box.querySelectorAll('[data-podium-horse]').forEach(b=>b.onclick=()=>inspectRunner(b.dataset.podiumHorse));
}
